        const msg = inTransit.values().next().value as Message;
        deliverMessage(msg);
      }
    },
    async timeout(id): Promise<Outcome> {
      const node = nodes.get(id);
      if (!node) return { ok: false, reason: `unknown node ${id}` };
      if (node.role === 'down') return { ok: false, reason: `${id} is down` };
      if (node.startedElection) return { ok: false, reason: `${id} already started an election` };
      if (node.role !== 'follower' || node.term !== 0) {
        return { ok: false, reason: `${id} is not a follower in term 0` };
      }
      node.startedElection = true;
      node.role = 'candidate';
      node.term = 1;
      node.votedFor = id;
      node.votes = new Set([id]);
      for (const other of NODE_IDS) {
        if (other !== id) send(id, other, 'RequestVote', { from: id, term: 1 });
      }
      return { ok: true };
    },
    async giveUp(id): Promise<Outcome> {
      const node = nodes.get(id);
      if (!node) return { ok: false, reason: `unknown node ${id}` };
      if (node.role !== 'candidate') return { ok: false, reason: `${id} is not a candidate` };
      // Stays in its term and keeps its vote for itself, so it grants no other vote.
      node.role = 'follower';
      return { ok: true };
    },
    async node(id) {
      const node = nodes.get(id);
      if (!node) return null;
      return { role: node.role, term: node.term, votedFor: node.votedFor, leader: node.leader };
    },
  };
  return host;
};

export default createHost;

