import { test } from 'node:test';
import assert from 'node:assert/strict';
import createHost from '../src/host.impl.ts';

const IDS = ['n0', 'n1', 'n2'];

test('single candidate wins', async () => {
  const h = await createHost();
  assert.deepEqual(await h.timeout('n0'), { ok: true });
  assert.equal((await h.timeout('n0')).ok, false);
  assert.equal((await h.timeout('x')).ok, false);
  assert.equal(await h.node('x'), null);
  const f = await h.inFlight();
  assert.equal(f.length, 2);
  assert.deepEqual(f[0].data, { from: 'n0', term: 1 });
  await h.deliverAll();
  assert.deepEqual(await h.node('n0'), { role: 'leader', term: 1, votedFor: 'n0', leader: 'n0' });
  assert.deepEqual(await h.node('n1'), { role: 'follower', term: 1, votedFor: 'n0', leader: 'n0' });
  assert.equal((await h.timeout('n1')).ok, false);
});

test('Leader to a term-0 node and to a candidate', async () => {
  const h = await createHost();
  await h.timeout('n0');
  await h.timeout('n2');
  // n1 votes for n0; n0 wins
  const f = await h.inFlight();
  await h.deliver(f.find((m) => m.from === 'n0' && m.to === 'n1')!.id);
  await h.deliver((await h.inFlight()).find((m) => m.action === 'VoteReply')!.id);
  assert.equal((await h.node('n0'))!.role, 'leader');
  const leaders = (await h.inFlight()).filter((m) => m.action === 'Leader');
  assert.equal(leaders.length, 2);
  assert.deepEqual(leaders[0].data, { from: 'n0', term: 1 });
  await h.deliver(leaders.find((m) => m.to === 'n2')!.id);
  assert.deepEqual(await h.node('n2'), { role: 'follower', term: 1, votedFor: 'n2', leader: 'n0' });

  const g = await createHost();
  await g.timeout('n0');
  await g.deliver((await g.inFlight()).find((m) => m.to === 'n1')!.id);
  await g.deliver((await g.inFlight()).find((m) => m.action === 'VoteReply')!.id);
  await g.deliver((await g.inFlight()).find((m) => m.action === 'Leader' && m.to === 'n2')!.id);
  assert.deepEqual(await g.node('n2'), { role: 'follower', term: 1, votedFor: null, leader: 'n0' });
  assert.equal((await g.timeout('n2')).ok, false);
  await g.deliverAll();
  assert.deepEqual(await g.node('n2'), { role: 'follower', term: 1, votedFor: 'n0', leader: 'n0' });
});

test('giveUp', async () => {
  const h = await createHost();
  assert.equal((await h.giveUp('n0')).ok, false);
  assert.equal((await h.giveUp('x')).ok, false);
  await h.timeout('n0');
  await h.timeout('n1');
  assert.deepEqual(await h.giveUp('n0'), { ok: true });
  assert.deepEqual(await h.node('n0'), { role: 'follower', term: 1, votedFor: 'n0', leader: null });
  assert.equal((await h.giveUp('n0')).ok, false);
  assert.equal((await h.timeout('n0')).ok, false);
  await h.deliverAll();
  // n0 refuses n1, n2 voted for whichever request arrived first
  const views = await Promise.all(IDS.map((n) => h.node(n)));
  assert.equal(views[0]!.role, 'follower');
  assert.equal(views[0]!.votedFor, 'n0');
  if (views[2]!.votedFor === 'n1') assert.equal(views[1]!.role, 'leader');
  else assert.equal(views[1]!.role, 'candidate');
});

test('random orders: at most one leader, leader has majority', async () => {
  for (let i = 0; i < 2000; i++) {
    const h = await createHost();
    for (const s of IDS) if (Math.random() < 0.7) await h.timeout(s);
    for (;;) {
      const f = await h.inFlight();
      if (!f.length) break;
      if (Math.random() < 0.1) await h.timeout(IDS[Math.floor(Math.random() * 3)]);
      if (Math.random() < 0.05) await h.giveUp(IDS[Math.floor(Math.random() * 3)]);
      await h.deliver(f[Math.floor(Math.random() * f.length)].id);
    }
    const views = await Promise.all(IDS.map((n) => h.node(n)));
    const leaders = IDS.filter((_, k) => views[k]!.role === 'leader');
    assert.ok(leaders.length <= 1);
    if (leaders.length) {
      assert.ok(views.filter((v) => v!.votedFor === leaders[0]).length >= 2);
      for (const v of views) if (v!.term === 1) assert.equal(v!.leader, leaders[0]);
    } else {
      for (const v of views) assert.equal(v!.leader, null);
    }
  }
});

